package events

import (
	"bytes"
	"database/sql"
	"encoding/json"
	"errors"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// PutSnapshot stores state as the snapshot of documentID at cursor, creating
// it on first use and reporting whether this call created it.
//
// Only cursors of existing changes are valid snapshot points: an unknown
// document, a cursor below 1 or a cursor ahead of the document's current
// cursor yields ErrSnapshotBase and nothing is written. The current cursor is
// the document's high-water mark in the never-reset cursor space — the
// greater of the online maximum and the compaction boundary — so a cursor
// whose change has been trimmed by compaction is still a valid snapshot
// point, even after a full trim emptied the online log. Re-posting a state
// that decodes equal to the stored one is idempotent (created=false); a
// different state is an *ErrSnapshotConflict and the stored snapshot is left
// unchanged. Snapshots are independent of the change log: they neither move
// the document's cursor nor affect merges.
func (s *Service) PutSnapshot(documentID string, cursor int64, state json.RawMessage) (bool, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	current, err := currentCursorTx(tx, documentID)
	if err != nil {
		return false, err
	}
	if current == 0 || cursor < 1 || cursor > current {
		return false, ErrSnapshotBase
	}

	var existing []byte
	err = tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO snapshots (document_id, cursor, state) VALUES (?, ?, ?)`,
			documentID, cursor, []byte(state),
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	default:
		if !store.JSONEqual(existing, state) {
			return false, &ErrSnapshotConflict{Cursor: cursor}
		}
		return false, nil
	}
}

// GetSnapshot returns the state stored for documentID at cursor. Any miss —
// unknown document, unknown cursor or absent snapshot — yields
// ErrSnapshotNotFound.
func (s *Service) GetSnapshot(documentID string, cursor int64) (json.RawMessage, error) {
	var state []byte
	err := s.db.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&state)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return nil, ErrSnapshotNotFound
	case err != nil:
		return nil, err
	default:
		return json.RawMessage(state), nil
	}
}

// ExportSnapshots returns every snapshot of documentID whose cursor lies in
// the closed interval [from, to], in ascending cursor order. When to is nil no
// upper bound is applied. An unknown document, or a range without a snapshot,
// yields an empty list and no error: the export is a read that misses like any
// other. The (document_id, cursor) primary key guarantees a cursor appears at
// most once.
//
// The single SELECT runs as one SQLite statement over the serialized
// connection, so a snapshot committed concurrently is observed either with all
// of its row or not at all — never half of it. The read starts no
// transaction, writes nothing and notifies no waiters, so it cannot move a
// cursor or produce a change record.
func (s *Service) ExportSnapshots(documentID string, from int64, to *int64) ([]ExportedSnapshot, error) {
	var (
		rows *sql.Rows
		err  error
	)
	if to == nil {
		rows, err = s.db.Query(
			`SELECT cursor, state FROM snapshots
			 WHERE document_id = ? AND cursor >= ?
			 ORDER BY cursor ASC`,
			documentID, from,
		)
	} else {
		rows, err = s.db.Query(
			`SELECT cursor, state FROM snapshots
			 WHERE document_id = ? AND cursor >= ? AND cursor <= ?
			 ORDER BY cursor ASC`,
			documentID, from, *to,
		)
	}
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ExportedSnapshot, 0)
	for rows.Next() {
		var snap ExportedSnapshot
		if err := rows.Scan(&snap.Cursor, &snap.State); err != nil {
			return nil, err
		}
		out = append(out, snap)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// RestoreSnapshot appends one ordinary change whose payload is the state of
// documentID's snapshot at snapshotCursor, all within a single serialized
// transaction.
//
//   - A snapshot miss (unknown document or a cursor without a snapshot)
//     returns ErrSnapshotNotFound; nothing is written.
//   - If changeID already belongs to a prior restore, the call is idempotent
//     only when deviceId, snapshotCursor and the decoded source state all
//     match; the first result (created=false, original cursor) is returned.
//   - If changeID is taken by an ordinary change, or a restore whose provenance
//     differs, the call returns *ErrRestoreConflict; nothing is written.
//
// Otherwise a new change is appended with the next document cursor and the
// restore provenance is recorded. Old rows are never modified.
func (s *Service) RestoreSnapshot(documentID, deviceID, changeID string, snapshotCursor int64) (RestoreResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return RestoreResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	result, err := restoreSnapshotTx(tx, documentID, deviceID, changeID, snapshotCursor)
	if err != nil {
		return RestoreResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return RestoreResult{}, err
	}
	// A genuinely new restore appended a change and is the only outcome that
	// wakes the long polls and pushes to subscribers; an idempotent repeat
	// appended nothing and notifies nothing.
	if result.Created {
		s.notifyWaiters(documentID)
	}
	return result, nil
}

// RestoreSnapshotAuthorized is the session-scoped restore: it has exactly the
// restore semantics of RestoreSnapshot, but enforces the gate (registration
// then permission) first in the same serialized transaction: an unregistered
// device yields store.ErrDeviceNotFound and a revoked device yields
// ErrPermissionDenied. None of those outcomes writes anything or observes
// snapshot or change content. The device identity is resolved from the session
// by the HTTP layer before the call.
func (s *Service) RestoreSnapshotAuthorized(documentID, deviceID, changeID string, snapshotCursor int64) (RestoreResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return RestoreResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first: the device row and the permission row are read before the
	// snapshot is looked up or any change content is observed, so a rejected
	// restore cannot reveal anything.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, deviceID); err != nil {
			return RestoreResult{}, err
		}
	}

	result, err := restoreSnapshotTx(tx, documentID, deviceID, changeID, snapshotCursor)
	if err != nil {
		return RestoreResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return RestoreResult{}, err
	}
	if result.Created {
		s.notifyWaiters(documentID)
	}
	return result, nil
}

// restoreSnapshotTx runs the snapshot lookup, the idempotency/conflict
// resolution and the single append inside the caller's serialized
// transaction. It is shared by the document-level restore and the
// session-scoped authorized restore so the two paths cannot drift: both take
// their snapshot miss (ErrSnapshotNotFound), conflict (*ErrRestoreConflict)
// and append decisions from one code path. The result's Created flag tells
// the caller whether a change-bearing transaction just committed and the push
// channels therefore need waking.
func restoreSnapshotTx(tx *sql.Tx, documentID, deviceID, changeID string, snapshotCursor int64) (RestoreResult, error) {
	// The snapshot must exist; its state is the payload to append.
	var state []byte
	err := tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, snapshotCursor,
	).Scan(&state)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return RestoreResult{}, ErrSnapshotNotFound
	case err != nil:
		return RestoreResult{}, err
	}

	// Resolve the change id: an ordinary row, a prior restore and a
	// compacted-away id's retained summary are handled differently, so consult
	// all three.
	var existingCursor int64
	var existingDevice string
	var existingPayload []byte
	err = tx.QueryRow(
		`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
		documentID, changeID,
	).Scan(&existingCursor, &existingDevice, &existingPayload)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No online row: the id may belong to a change compaction trimmed.
		// Its retained summary still decides — an idempotent restore needs the
		// same device, snapshot cursor and source state; an id left by an
		// ordinary trimmed change is a conflict, as is any mismatch.
		var summaryDevice string
		var summaryDigest []byte
		var summaryCursor int64
		var restoredFrom sql.NullInt64
		err := tx.QueryRow(
			`SELECT device_id, digest, cursor, restored_from FROM change_identities
			 WHERE document_id = ? AND id = ?`,
			documentID, changeID,
		).Scan(&summaryDevice, &summaryDigest, &summaryCursor, &restoredFrom)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// Genuinely new id; fall through to append below.
		case err != nil:
			return RestoreResult{}, err
		default:
			stateDigest, err := payloadDigest(state)
			if err != nil {
				return RestoreResult{}, err
			}
			if !restoredFrom.Valid || restoredFrom.Int64 != snapshotCursor ||
				summaryDevice != deviceID || !bytes.Equal(summaryDigest, stateDigest) {
				return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
			}
			return RestoreResult{
				ID:           changeID,
				Created:      false,
				Cursor:       summaryCursor,
				RestoredFrom: snapshotCursor,
			}, nil
		}
	case err != nil:
		return RestoreResult{}, err
	default:
		var restDevice string
		var restSnapshotCursor int64
		var restState []byte
		err = tx.QueryRow(
			`SELECT device_id, snapshot_cursor, state FROM restores WHERE document_id = ? AND change_id = ?`,
			documentID, changeID,
		).Scan(&restDevice, &restSnapshotCursor, &restState)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// The id belongs to an ordinary change (or a batch/merge change),
			// not a restore: never treat it as an idempotent restore.
			return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
		case err != nil:
			return RestoreResult{}, err
		default:
			if restDevice != deviceID || restSnapshotCursor != snapshotCursor || !store.JSONEqual(restState, state) {
				return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
			}
			return RestoreResult{
				ID:           changeID,
				Created:      false,
				Cursor:       existingCursor,
				RestoredFrom: snapshotCursor,
			}, nil
		}
	}

	nextCursor, err := currentCursorTx(tx, documentID)
	if err != nil {
		return RestoreResult{}, err
	}
	nextCursor++
	if _, err := tx.Exec(
		`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
		documentID, nextCursor, changeID, deviceID, state,
	); err != nil {
		return RestoreResult{}, err
	}
	if _, err := tx.Exec(
		`INSERT INTO restores (document_id, change_id, device_id, snapshot_cursor, change_cursor, state)
		 VALUES (?, ?, ?, ?, ?, ?)`,
		documentID, changeID, deviceID, snapshotCursor, nextCursor, state,
	); err != nil {
		return RestoreResult{}, err
	}
	return RestoreResult{
		ID:           changeID,
		Created:      true,
		Cursor:       nextCursor,
		RestoredFrom: snapshotCursor,
	}, nil
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// snapshotExportItem is one element of an export body. The struct field order
// fixes the on-the-wire key order to cursor then state; State is embedded as
// raw JSON so the stored content is emitted verbatim, exactly as the single
// snapshot read emits it.
type snapshotExportItem struct {
	Cursor int64           `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

// snapshotExportResponse is the export body with the top-level key order fixed
// to snapshots then count. Snapshots is always a non-nil slice so an empty
// export serializes as [] rather than null.
type snapshotExportResponse struct {
	Snapshots []snapshotExportItem `json:"snapshots"`
	Count     int                  `json:"count"`
}

// handleExportSnapshots is the read-only batch export over a document's
// snapshot collection:
//
//	GET /v1/documents/{documentID}/snapshots?from=0&to=N
//
// from defaults to 0; to absent means no upper bound. Only snapshots whose
// cursor is in the closed [from, to] interval are returned, in ascending
// cursor order, at most one entry per cursor. An unknown document or a range
// without any snapshot is a successful 200 with an empty list and count 0, not
// an error. The handler writes nothing: it creates no snapshot, moves no
// cursor, records no change and notifies the push channels.
func handleExportSnapshots(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	snaps, err := s.ExportSnapshots(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export snapshots")
		return
	}
	writeSnapshotExport(w, snaps)
}

// writeSnapshotExport renders an export result in the shared response shape: a
// single compact JSON line with the snapshots,count key order, each item
// keyed cursor,state, an empty export serializing as [] with count 0. It is
// shared by the document-scoped and session-scoped exports so their bodies
// cannot drift apart.
func writeSnapshotExport(w http.ResponseWriter, snaps []events.ExportedSnapshot) {
	items := make([]snapshotExportItem, 0, len(snaps))
	for _, snap := range snaps {
		items = append(items, snapshotExportItem{Cursor: snap.Cursor, State: snap.State})
	}
	writeJSON(w, http.StatusOK, snapshotExportResponse{Snapshots: items, Count: len(items)})
}

// handleSessionExportSnapshots is the session-scoped view of the snapshot
// batch export, over the session document-read prefix with the resource
// segment swapped to the snapshot collection:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/snapshots?from=0&to=N
//
// The interval semantics and the response body are identical to the
// document-level export; the path offers no other read form, so every GET is
// the export (from/to absent means the default interval). Around the export
// sit the session view's checks in their fixed order — request shape and
// parameters (400), session existence (404), the session device's document
// permission (403) — so a rejected export exposes no snapshot content and
// writes nothing.
func handleSessionExportSnapshots(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Malformed interval parameters are a request-shape error (400) checked
	// before the resource lookup (404), matching the session change export's
	// ordering.
	from, to, ok := parseExportInterval(w, r.URL.Query())
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	snaps, err := s.ExportSnapshots(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export snapshots")
		return
	}
	writeSnapshotExport(w, snaps)
}

// malformedSnapshotPath reports whether p targets the snapshot namespace but
// is not at one of its two exact locations:
//
//	GET  /v1/documents/{documentID}/snapshots          (the batch export)
//	GET  /v1/documents/{documentID}/snapshots/{cursor} (the single read)
//
// A trailing slash (an empty cursor segment, including the collection path
// with a trailing slash), extra path segments, or a "snapshots" segment in any
// keyword position short of one of those shapes is a malformed 400 rather than
// ServeMux's redirect or plain-text 404/405: the snapshot endpoints promise a
// JSON error and never a redirect. Empty segments are already rejected by the
// guard itself. The keyword is matched only past the documentID position, so a
// document literally named "snapshots" keeps its ordinary routes.
func malformedSnapshotPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg != "snapshots" || i == 0 {
			continue
		}
		// Keyword position reached. The collection is exactly
		// {documentID}/snapshots; the single read adds one non-empty cursor
		// segment. Anything else (trailing slash, missing/extra segments) is
		// malformed.
		collection := len(segs) == 2 && segs[0] != ""
		item := len(segs) == 3 && segs[0] != "" && segs[2] != ""
		return !(collection || item)
	}
	return false
}

// malformedSessionSnapshotsPath reports whether p targets the session-scoped
// snapshot collection's shape but is not the collection's exact location
// (/v1/sessions/{sessionId}/documents/{documentId}/snapshots): extra path
// segments past the collection (the session view has no single-snapshot
// item, so a trailing cursor segment is malformed too). ServeMux would answer
// those with a plain-text 404; the snapshot surface promises a JSON 400 and
// never a redirect. Empty segments (doubled slashes, a trailing slash) are
// already rejected by the guard itself.
//
// "snapshots" is treated as the collection keyword only in the fourth
// segment, right after the document identifier; a session or document
// identifier literally named "snapshots" occupies an identifier position and
// keeps its ordinary routes.
func malformedSessionSnapshotsPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/sessions/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guard; "snapshots" there is an ordinary identifier, not
	// this collection's keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	if len(segs) < 4 || segs[1] != "documents" || segs[3] != "snapshots" {
		return false
	}
	// Keyword position reached. The collection is exactly
	// {sessionId}/documents/{documentId}/snapshots; anything past it is a
	// malformed 400.
	return !(len(segs) == 4 && segs[0] != "" && segs[2] != "")
}

package server

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log"
	"mime"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// maxBatchBytes caps an inbound POST body.
const maxBatchBytes = 10 << 20

// defaultListLimit is used when GET omits limit.
const defaultListLimit = 100

// maxListLimit is the largest page size GET accepts.
const maxListLimit = 1000

// maxPollWaitMillis is the longest waitMs a long poll accepts.
const maxPollWaitMillis = 30000

type changeIn struct {
	ID      string          `json:"id"`
	Payload json.RawMessage `json:"payload"`
}

type postRequest struct {
	DeviceID string     `json:"deviceId"`
	Changes  []changeIn `json:"changes"`
}

type mergeChangeIn struct {
	ID      string          `json:"id"`
	Payload json.RawMessage `json:"payload"`
}

type mergeRequest struct {
	DeviceID   string          `json:"deviceId"`
	BaseCursor json.RawMessage `json:"baseCursor"`
	Change     *mergeChangeIn  `json:"change"`
}

type snapshotPostRequest struct {
	Cursor json.RawMessage `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

type restoreRequest struct {
	DeviceID       string          `json:"deviceId"`
	ChangeID       string          `json:"changeId"`
	SnapshotCursor json.RawMessage `json:"snapshotCursor"`
}

type deviceRequest struct {
	DeviceID string `json:"deviceId"`
}

type permissionRequest struct {
	DeviceID string `json:"deviceId"`
	Action   string `json:"action"`
}

type sessionRequest struct {
	SessionID string `json:"sessionId"`
}

type sessionPostRequest struct {
	Changes []changeIn `json:"changes"`
}

// sessionReplayRequest is the session-scoped replay body: only the ordered
// operations array travels in the request. The calling device is the session's
// owning device resolved from the path, so a stray deviceId is decoded and
// ignored like every other unknown field.
type sessionReplayRequest struct {
	Operations []changeIn `json:"operations"`
}

type replayRequest struct {
	DeviceID   string     `json:"deviceId"`
	Operations []changeIn `json:"operations"`
}

// NewHandlerWithReadiness builds the same public HTTP surface as NewHandler but
// answers every request — including GET /healthz — with a 503 JSON error until
// ready reports that the database is open and the listener is accepting
// connections. Once ready, responses are byte-for-byte what NewHandler emits;
// readiness is one-way, so a later flip back is not part of the contract.
func NewHandlerWithReadiness(s *app.App, ready func() bool) http.Handler {
	h := NewHandler(s)
	if ready == nil {
		return h
	}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !ready() {
			writeError(w, http.StatusServiceUnavailable, "service is not ready")
			return
		}
		h.ServeHTTP(w, r)
	})
}

// NewHandler builds the public HTTP surface backed by s.
func NewHandler(s *app.App) http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})

	mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
		handleRegisterDevice(s, w, r)
	})
	mux.HandleFunc("DELETE /v1/devices/{deviceId}", func(w http.ResponseWriter, r *http.Request) {
		handleDeregisterDevice(s, w, r)
	})
	// The device item path accepts only DELETE (deregistration); every other
	// verb gets a JSON 400 rather than the subtree's unknown-path JSON 404.
	mux.HandleFunc("/v1/devices/{deviceId}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	// A DELETE short of the device id misses the segment that names the
	// deregistering device; answer a JSON 400 instead of the collection's
	// unknown-path JSON 404.
	mux.HandleFunc("DELETE /v1/devices", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "device deregistration path is malformed")
	})
	// Non-POST verbs on the exact collection path: the method-less pattern is
	// less specific than POST above, so it only catches the rest and answers a
	// JSON 404 instead of ServeMux's slash redirect. The explicit DELETE
	// pattern above wins for a bodyless deregistration missing its id segment.
	mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusNotFound, "unknown device path")
	})
	mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusNotFound, "unknown session path")
	})
	mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
		handleCreateSession(s, w, r)
	})
	mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
		handleDeleteSession(s, w, r)
	})
	// Device-scoped subscription management: a read-only list of the device's
	// live push connections and a DELETE that actively cancels one of them.
	// The path device id is the only identity, exactly like the session
	// routes above it.
	mux.HandleFunc("GET /v1/devices/{deviceId}/subscriptions", func(w http.ResponseWriter, r *http.Request) {
		handleListDeviceSubscriptions(s, w, r)
	})
	mux.HandleFunc("DELETE /v1/devices/{deviceId}/subscriptions/{subscriptionId}", func(w http.ResponseWriter, r *http.Request) {
		handleCancelDeviceSubscription(s, w, r)
	})
	// The collection path accepts only GET and the item path only DELETE;
	// every other verb on either exact shape gets a JSON 400 rather than
	// ServeMux's plain-text 405.
	mux.HandleFunc("/v1/devices/{deviceId}/subscriptions", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
