// sessionMergeRequest is the session-scoped merge body: only the observed base
// cursor and the single change travel in the request. The calling device is the
// session's owning device resolved from the path, so a stray deviceId is
// decoded and ignored like every other unknown field.
type sessionMergeRequest struct {
	BaseCursor json.RawMessage `json:"baseCursor"`
	Change     *mergeChangeIn  `json:"change"`
}

// handleSessionMergeChange is the session-scoped single-change merge entry,
// the session view's counterpart to
// POST /v1/documents/{documentID}/merge, mounted one segment below the change
// collection:
//
//	POST /v1/sessions/{sessionId}/documents/{documentId}/changes/merge
//
// The body carries only baseCursor and one change; the calling device is the
// session's owning device resolved from the path with the same identity rule as
// the session reads, exports, commits, replays, polls and subscriptions — no
// new credential is introduced, and a stray deviceId in the body is ignored
// like any other unknown field. The merge judgment, success body and cursor
// space are byte-identical to the document-level merge: a single result naming
// the id, its three-way outcome ("applied", "merged" or "idempotent") and the
// cursor it received, with the original result attached only when nothing was
// created. The checks run in the fixed order request shape (400), session
// existence (404), document permission (403) — the permission verdict is taken
// inside the merge transaction, so a revoked device writes nothing — and the
// in-transaction merge failures (a stale or compacted base cursor, an
// id/payload/source mismatch, a key collision or a non-object later payload)
// answer 400 or 409 with zero writes.
func handleSessionMergeChange(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	var req sessionMergeRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	// baseCursor must be present and a non-negative integer (no fractions,
	// strings, booleans or null).
	if len(req.BaseCursor) == 0 {
		writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
		return
	}
	baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
	if !ok {
		writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
		return
	}
	if req.Change == nil {
		writeError(w, http.StatusBadRequest, "change must be an object")
		return
	}
	if req.Change.ID == "" {
		writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
		return
	}
	if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
		writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
		return
	}

	// Request shape is settled; only now does the session lookup run, so a
	// malformed merge against an unknown session is still a 400.
	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	result, err := s.MergeSessionChange(documentID, baseCursor, events.Change{
		ID:       req.Change.ID,
		DeviceID: deviceID,
		Payload:  req.Change.Payload,
	})
	if err != nil {
		var conflict *events.ErrConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			// The session's device was deregistered between the lookup and the
			// merge; its cascade removed the session too, so the identity the
			// caller used no longer exists.
			writeError(w, http.StatusNotFound, "session not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.Is(err, events.ErrStaleCursor):
			writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
		case errors.Is(err, events.ErrCompactedBase):
			writeError(w, http.StatusBadRequest, "baseCursor is below the compaction boundary")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
		default:
			writeError(w, http.StatusInternalServerError, "failed to merge change")
		}
		return
	}

	writeJSON(w, http.StatusOK, result)
}

// parseChangesQuery parses the shared after/limit pagination parameters,
// writing the documented 400 on an illegal value. It is shared by the
// document-scoped and session-scoped change listings so their query semantics
// cannot drift apart.
func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
	q := r.URL.Query()

	after = 0
	if raw := q.Get("after"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 {
			writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
			return 0, 0, false
		}
		after = v
	}

	limit = defaultListLimit
	if raw := q.Get("limit"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 1 || v > maxListLimit {
			writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
			return 0, 0, false
		}
		limit = v
	}

	return after, limit, true
}

// writeChangesPage renders a change listing page in the shared response shape.
func writeChangesPage(w http.ResponseWriter, changes []events.ListedChange, nextCursor int64) {
	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
	})
}

// parsePollWaitMs parses the long-poll waitMs query parameter, writing the
// documented 400 on an illegal value. It accepts an integer in 0..30000
// milliseconds and defaults to 0 when the parameter is absent; a value outside
// the range, a fraction, an exponent or any non-numeric value is rejected. It
// is shared by the document-scoped and session-scoped long polls so their wait
// semantics cannot drift apart.
func parsePollWaitMs(w http.ResponseWriter, r *http.Request) (int64, bool) {
	var waitMs int64
	if raw := r.URL.Query().Get("waitMs"); raw != "" {
		v, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || v < 0 || v > maxPollWaitMillis {
			writeError(w, http.StatusBadRequest, "waitMs must be an integer between 0 and 30000")
			return 0, false
		}
		waitMs = v
	}
	return waitMs, true
}

// writePollPage renders a long-poll result in the shared response shape: the
// ordinary page plus a timedOut flag, with the top-level keys in the fixed
// changes, nextCursor, timedOut order.
func writePollPage(w http.ResponseWriter, changes []events.ListedChange, nextCursor int64, timedOut bool) {
	writeJSON(w, http.StatusOK, map[string]any{
		"changes":    changes,
		"nextCursor": nextCursor,
		"timedOut":   timedOut,
	})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, map[string]string{"error": message})
}

// handlePollChanges is the long-polling entry over the change log.
//
// Query params share the existing change-read constraints: after is a
// non-negative cursor (default 0) and limit is 1..1000 (default 100); waitMs
// is 0..30000 (default 0). Rows already past after return immediately; a known
// document caught up to after parks until the first new commit or the wait
// deadline; an unknown document returns an empty page with cursor 0 at once.
// The response shape is the ordinary page plus a timedOut flag; a deadline
// expiry echoes the caller's cursor and never advances it. A client
// disconnect simply stops the wait and writes nothing.
func handlePollChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}
	waitMs, ok := parsePollWaitMs(w, r)
	if !ok {
		return
	}

	changes, nextCursor, timedOut, err := s.WaitForChanges(
		r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
	)
	switch {
	case errors.Is(err, events.ErrStoreClosing):
		writeError(w, http.StatusServiceUnavailable, "service is shutting down")
		return
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		// The client went away (or, with waitMs bounded, its deadline lapsed
		// at the transport): nothing more to write and nothing was stored.
		return
	case err != nil:
		writeError(w, http.StatusInternalServerError, "failed to poll changes")
		return
	}

	writePollPage(w, changes, nextCursor, timedOut)
}

// handleSessionPollChanges is the session-scoped long-poll continuation over
// the same change collection the session reads page:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes/poll
//
// The request is a GET with no body; the calling device is the session's
// owning device resolved with the same identity rule as the session reads,
// exports, commits and subscriptions. Query parameters and the success body are
// identical to GET /v1/documents/{documentID}/changes/poll — after (default 0),
// limit (default 100, 1..1000) and waitMs (default 0, 0..30000), answered with
// changes, nextCursor and timedOut in that order, rows ascending by cursor.
//
// Rows already past after return immediately with timedOut=false; a known
// document caught up to after parks until the first commit through any write
// path (session batch commit, document commit, merge, restore, replay) or the
// wait deadline; an unknown document returns an empty page with cursor 0 at
// once and never parks. A deadline expiry returns the empty page, echoes the
// caller's after and sets timedOut=true without advancing the cursor. Checks
// run in the fixed order request shape and parameters (400), session
// existence (404), document permission (403); a rejected request exposes no
// change content. A client disconnect simply cancels the wait and writes
// nothing; while the service is shutting down the parked request answers a
// JSON 503.
func handleSessionPollChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Parameter shape precedes the session lookup, matching the session paged
	// read's ordering: a malformed after/limit/waitMs against an unknown
	// session is still a 400.
	after, limit, ok := parseChangesQuery(w, r)
	if !ok {
		return
	}
	waitMs, ok := parsePollWaitMs(w, r)
	if !ok {
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	changes, nextCursor, timedOut, err := s.WaitForChanges(
		r.Context(), documentID, after, limit, time.Duration(waitMs)*time.Millisecond,
	)
	switch {
	case errors.Is(err, events.ErrStoreClosing):
		writeError(w, http.StatusServiceUnavailable, "service is shutting down")
		return
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		// The client went away (or, with waitMs bounded, its deadline lapsed
		// at the transport): nothing more to write and nothing was stored.
		return
	case err != nil:
		writeError(w, http.StatusInternalServerError, "failed to poll changes")
		return
	}

	writePollPage(w, changes, nextCursor, timedOut)
}

// handleReplay retries an offline batch against the existing change log. The
// request and per-element semantics mirror POST .../changes — strict
// application/json body, non-empty ids, no in-batch duplicates, idempotent only
// when deviceId and decoded payload match, otherwise 409 reporting the
// conflicting id — with the registration/permission layer enforced first:
// 404 for an unregistered device and 403 for a revoked one, neither exposing
// change content. The whole batch commits in one serialized transaction that
// shares the document's contiguous cursor space with ordinary commits.
func handleReplay(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req replayRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	if req.Operations == nil {
		writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
		return
	}
	if len(req.Operations) == 0 {
		writeError(w, http.StatusBadRequest, "operations must be a non-empty array")
		return
	}

	changes := make([]events.Change, len(req.Operations))
	seen := make(map[string]struct{}, len(req.Operations))
	for i, op := range req.Operations {
		if op.ID == "" {
			writeError(w, http.StatusBadRequest, "each operation must have a non-empty string id")
			return
		}
		if len(op.Payload) == 0 {
			writeError(w, http.StatusBadRequest, "each operation must carry a JSON payload")
			return
		}
		if _, dup := seen[op.ID]; dup {
			writeError(w, http.StatusBadRequest, "duplicate operation id within batch: "+op.ID)
			return
		}
		seen[op.ID] = struct{}{}
		changes[i] = events.Change{ID: op.ID, DeviceID: req.DeviceID, Payload: op.Payload}
	}

	results, err := s.ReplayChanges(documentID, changes)
	if err != nil {
		var conflict *events.ErrConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.As(err, &conflict):
			writeJSON(w, http.StatusConflict, map[string]string{
				"error":      "operation id already exists with different deviceId or payload",
				"conflictId": conflict.ID,
			})
		default:
			writeError(w, http.StatusInternalServerError, "failed to replay operations")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

// Package store is the durable kernel shared by the internal services: it
// owns the SQLite database handle and the registration layer (devices and
// sessions) plus resumable attachments.
//
// The business services layered on top of the kernel — the change event log,
// the permission ledger and the CRDT state — live in their own packages and
// cooperate only through their internal interfaces. They all share this one
// handle: it opens a single pooled connection with immediate write
// transactions, so every service's transactional judgment is serialized on
// the same connection and no batch is ever half written.
//
// Devices and sessions form the registration layer. A device registers with a
// client-supplied id; a session belongs to exactly one registered device and
// is addressed by its own client-supplied id. Registration and session
// creation are idempotent re-posts: the first call creates, an identical
// repeat does not. A session id already owned by another device is a
// conflict, never silently re-homed. Deletes are owner-scoped and hard: a
// repeat delete, another device, and a cross-device path all miss with 404,
// after which the id is free to be created again. A device itself can
// deregister: the device row and everything it owns — its sessions and the
// attachments it created, chunks and grants included — vanish in one
// serialized transaction, a repeat or never-registered deregistration misses
// with 404 and writes nothing, and the freed id registers again as a
// brand-new device.
//
// Attachments are resumable chunked uploads owned by the registered device
// that created them. Creation pins the declared total size, chunk size and
// SHA-256 digest; chunks land in any order and are stored durably as they
// arrive, so an interrupted upload resumes after a restart with its
// idempotency and conflict decisions intact. Finishing concatenates the
// chunks, verifies the digest and seals the upload; a sealed upload is
// immutable and rejects every further chunk write. Finished content is
// addressed by digest, so a second attachment with the same digest and size
// reuses the stored bytes instead of copying them. The creator may grant
// other registered devices read-only access per attachment; every
// (attachment, device) pair starts unauthorized, grants and revokes commit in
// the same serialized way, and access never widens the write paths. Deletes
// are owner-scoped and hard: the record, its chunks and its grants vanish in
// one serialized transaction, a repeat delete misses with 404, the id is free
// to be created again, and the shared content bytes are reclaimed once the
// last completed attachment referencing them is gone.
package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"

	_ "modernc.org/sqlite"
)

// ErrDeviceNotFound reports that an operation targets a device id that was
// never registered. Services map it to 404; nothing is written.
var ErrDeviceNotFound = errors.New("device not found")

// ErrPermissionDenied reports that a device's access to a document has been
// revoked. Services map it to 403; nothing is written and no document content
// is exposed. It is a shared verdict produced by the permission service and
// consulted by every service that enforces the gate inside a transaction.
var ErrPermissionDenied = errors.New("device permission for this document has been revoked")

// ErrSessionConflict reports that a session id already belongs to a different
// device. The session keeps its original owner; nothing is written. Services
// map it to 409.
type ErrSessionConflict struct {
	ID string
}

func (e *ErrSessionConflict) Error() string {
	return fmt.Sprintf("session %q belongs to another device", e.ID)
}

// ErrSessionNotFound reports that no live session matches the (device,
// session) pair: the session was never created, was already deleted, or
// belongs to another device. Services map it to 404.
var ErrSessionNotFound = errors.New("session not found")

// DBTX is the subset of *sql.DB and *sql.Tx the services use for their
// serialized work, so judgments made "in the same transaction" (for example a
// permission gate followed by the gated write) run on one concrete connection
// whether the caller holds a transaction or the handle itself.
type DBTX interface {
	Exec(query string, args ...any) (sql.Result, error)
	Query(query string, args ...any) (*sql.Rows, error)
	QueryRow(query string, args ...any) *sql.Row
}

// Store is the durable kernel: one SQLite database handle together with the
// device, session and attachment data it owns.
type Store struct {
	db *sql.DB
}

// Open opens (creating if needed) the SQLite database at path. The empty path
// opens an in-memory database useful for tests.
func Open(path string) (*Store, error) {
	if path == "" {
		// With a single pooled connection this is a private, per-instance
		// in-memory database (useful for tests).
		path = "file::memory:"
	}
	// _txlock=immediate makes writers acquire the write lock at BEGIN, so
	// concurrent batches serialize without SQLITE_BUSY deadlocks.
	dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	// One connection avoids cross-connection locking surprises; writes are
	// serialized by the immediate transaction anyway, and SQLite concurrency
	// for readers does not help correctness here. It also keeps every
	// service's transaction serialized on the same connection.
	db.SetMaxOpenConns(1)
	s := &Store{db: db}
	if err := s.init(); err != nil {
		_ = db.Close()
		return nil, err
	}
	return s, nil
}

// DB returns the underlying handle. The business services use it to open the
// serialized transactions their judgments run in; callers outside the
// internal packages never need it.
func (s *Store) DB() *sql.DB { return s.db }

// Close releases the database handle.
func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) init() error {
	_, err := s.db.Exec(`
CREATE TABLE IF NOT EXISTS devices (
	id TEXT NOT NULL PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS sessions (
	id        TEXT NOT NULL PRIMARY KEY,
	device_id TEXT NOT NULL REFERENCES devices(id)
);
CREATE INDEX IF NOT EXISTS sessions_device_idx
	ON sessions(device_id);
CREATE TABLE IF NOT EXISTS attachments (
	id          TEXT NOT NULL PRIMARY KEY,
	device_id   TEXT NOT NULL REFERENCES devices(id),
	total_bytes INTEGER NOT NULL,
	chunk_size  INTEGER NOT NULL,
	sha256      TEXT NOT NULL,
	complete    INTEGER NOT NULL DEFAULT 0,
	reused      INTEGER NOT NULL DEFAULT 0,
	created_seq INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS attachment_chunks (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	idx           INTEGER NOT NULL,
	data          BLOB NOT NULL,
	PRIMARY KEY (attachment_id, idx)
);
CREATE TABLE IF NOT EXISTS attachment_contents (
	sha256 TEXT NOT NULL PRIMARY KEY,
	size   INTEGER NOT NULL,
	data   BLOB NOT NULL
);
CREATE TABLE IF NOT EXISTS attachment_access (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	device_id     TEXT NOT NULL,
	authorized    INTEGER NOT NULL,
	granted_seq   INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY (attachment_id, device_id)
);
`)
	if err != nil {
		return err
	}
	if err := s.ensureAttachmentCreatedSeq(); err != nil {
		return err
	}
	return s.ensureAttachmentAccessGrantedSeq()
}

// ensureAttachmentCreatedSeq adds the creation-order column to databases
// created before it existed. Existing rows are backfilled in insertion
// (rowid) order so their relative listing order is unchanged; new rows take
// strictly larger values, so the sequence never reuses a value even after
// the newest attachment is deleted and its id created again.
func (s *Store) ensureAttachmentCreatedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachments)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "created_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachments ADD COLUMN created_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachments SET created_seq = (
			SELECT COUNT(*) FROM attachments older WHERE older.rowid <= attachments.rowid
		)`,
	)
	return err
}

// ensureAttachmentAccessGrantedSeq adds the grant-order column to access
// tables created before it existed. Existing rows are backfilled one past the
// per-attachment maximum in insertion (rowid) order, so surviving grants keep
// a stable relative order; every new grant takes a strictly larger value, even
// after the previously newest grant was revoked, so a re-granted device lists
// at the position of its latest grant and a value is never reused.
func (s *Store) ensureAttachmentAccessGrantedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachment_access)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "granted_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachment_access ADD COLUMN granted_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachment_access SET granted_seq = (
			SELECT rn FROM (
				SELECT rowid AS rid,
				       ROW_NUMBER() OVER (PARTITION BY attachment_id ORDER BY rowid) AS rn
				FROM attachment_access
			) WHERE rid = attachment_access.rowid
		)`,
	)
	return err
}

// RegisterDevice registers a device by client-supplied id. The first call for
// an id creates it and reports created=true; repeating the registration is
// idempotent (created=false). Device identity never changes.
func (s *Store) RegisterDevice(deviceID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	created, err = RegisterDeviceTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	return created, tx.Commit()
}

// RegisterDeviceTx is RegisterDevice against an existing transaction, so the
// services can resolve the registration layer as the first step of a larger
// serialized transaction (their permission/content gates then share it).
func RegisterDeviceTx(q DBTX, deviceID string) (created bool, err error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	if !exists {
		if _, err := q.Exec(`INSERT INTO devices (id) VALUES (?)`, deviceID); err != nil {
			return false, err
		}
		return true, nil
	}
	return false, nil
}

// DeviceExistsTx reports whether deviceID is registered, evaluated inside q so
// a service's gate runs on the same transaction as the work it guards.
func DeviceExistsTx(q DBTX, deviceID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// CreateSession creates a session owned by deviceID with a client-supplied id.
//
//   - An unknown device yields ErrDeviceNotFound; nothing is written.
//   - A session id already owned by another device yields *ErrSessionConflict;
//     nothing is written and the owner is unchanged.
//   - Re-posting the same (device, session) pair is idempotent: created=false.
//
// A deleted session is gone for good, so its id can be registered again as a
// brand-new session (created=true). The lookup, owner check and insert run in
// one serialized transaction, so concurrent creates of the same session id
// cannot both create it.
func (s *Store) CreateSession(deviceID, sessionID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO sessions (id, device_id) VALUES (?, ?)`,
			sessionID, deviceID,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if owner != deviceID {
		return false, &ErrSessionConflict{ID: sessionID}
	}
	return false, tx.Commit()
}

// DeleteSession removes the live session matching the (deviceID, sessionID)
// pair. Any miss — the session does not exist, was already deleted, or belongs
// to another device — returns ErrSessionNotFound and changes nothing. The
// check and the delete run in one transaction, so a concurrent create cannot
// interleave and a repeat delete still misses; the removal is committed to
// disk before the call returns.
func (s *Store) DeleteSession(deviceID, sessionID string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return ErrSessionNotFound
	case err != nil:
		return err
	}
	if owner != deviceID {
		return ErrSessionNotFound
	}

	if _, err := tx.Exec(
		`DELETE FROM sessions WHERE id = ? AND device_id = ?`,
		sessionID, deviceID,
	); err != nil {
		return err
	}
	return tx.Commit()
}

// DeleteDeviceTx deregisters deviceID and removes every record it owns, all
// inside the caller's serialized transaction:
//
//   - the device's sessions are hard-deleted, so their session-scoped reads
//     and subscriptions miss from then on;
//   - every attachment it created is removed together with its chunks, its
//     sealed/unfinished state and the access rows other devices held on it;
//   - the read grants the device itself held on other devices' attachments
//     are withdrawn;
//   - the device row is removed last (every child row goes first).
//
// Digest-addressed content is shared across attachments and is reclaimed only
// when no completed attachment still references a digest — exactly the rule
// of a single attachment delete — so another device's attachment with the same
// digest keeps its bytes and one deregistration by itself never reclaims
// shared content. The document permission ledger lives in the authz package
// and clears its own rows against the same transaction through
// DeleteDevicePermissionsTx.
//
// An unknown (never registered or already deregistered) device yields
// ErrDeviceNotFound and writes nothing. Because the whole judgment runs in one
// immediate transaction on the single shared connection, concurrent
// deregistrations of the same device commit at most once and any concurrent
// chunk upload or finish either committed entirely before it or is rejected
// entirely afterward — no half-written record survives.
func DeleteDeviceTx(q DBTX, deviceID string) error {
	exists, err := DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return ErrDeviceNotFound
	}

	// Remember the digests of the device's completed attachments before their
	// rows vanish: each is a candidate for content reclamation once every
	// owned attachment is gone. DISTINCT because several of the device's
	// attachments may share the same digest-addressed content.
	rows, err := q.Query(
		`SELECT DISTINCT sha256 FROM attachments WHERE device_id = ? AND complete = 1`,
		deviceID,
	)
	if err != nil {
		return err
	}
	var digests []string
	for rows.Next() {
		var digest string
		if err := rows.Scan(&digest); err != nil {
			_ = rows.Close()
			return err
		}
		digests = append(digests, digest)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}

	// Withdraw the read grants this device held on other devices'
	// attachments (rows naming it as the grantee), then remove the access
	// rosters of the attachments it created before the attachment rows those
	// rosters reference are deleted.
	if _, err := q.Exec(
		`DELETE FROM attachment_access WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_access
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_chunks
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachments WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}

	// Reclaim each digest-addressed content only when no surviving completed
	// attachment — owned by another device, or by the deregistered device in
	// an impossible re-read — still references it.
	for _, digest := range digests {
		var stillReferenced bool
		if err := q.QueryRow(
			`SELECT EXISTS(SELECT 1 FROM attachments WHERE sha256 = ? AND complete = 1)`,
			digest,
		).Scan(&stillReferenced); err != nil {
			return err
		}
		if !stillReferenced {
			if _, err := q.Exec(
				`DELETE FROM attachment_contents WHERE sha256 = ?`, digest,
			); err != nil {
				return err
			}
		}
	}

	if _, err := q.Exec(
		`DELETE FROM sessions WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM devices WHERE id = ?`, deviceID,
	); err != nil {
		return err
	}
	return nil
}

// DeviceExists reports whether a live device with deviceID is registered. It
// is the non-transactional counterpart to DeviceExistsTx, used by the
// document-level subscription handlers whose existence verdict runs before
// the WebSocket upgrade rather than inside a write transaction.
func (s *Store) DeviceExists(deviceID string) (bool, error) {
	return DeviceExistsTx(s.db, deviceID)
}

// SessionExists reports whether a live session with sessionID exists.
// Ownership is intentionally not part of this check: session-scoped reads only
// require that the session currently exists.
func (s *Store) SessionExists(sessionID string) (bool, error) {
	var exists bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM sessions WHERE id = ?)`, sessionID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// SessionDevice returns the id of the device that owns the live session
// sessionID. A session that was never created or was deleted yields
// ErrSessionNotFound.
func (s *Store) SessionDevice(sessionID string) (string, error) {
	var deviceID string
	err := s.db.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&deviceID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return "", ErrSessionNotFound
	case err != nil:
		return "", err
	default:
		return deviceID, nil
	}
}

// JSONEqual reports whether two payloads are equal after JSON decoding, so
// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal. It is shared
// verbatim by the change event and CRDT services' idempotency judgments.
func JSONEqual(a, b json.RawMessage) bool {
	var va, vb any
	if err := json.Unmarshal(a, &va); err != nil {
		return false
	}
	if err := json.Unmarshal(b, &vb); err != nil {
		return false
	}
	return deepEqual(va, vb)
}

func deepEqual(a, b any) bool {
	switch av := a.(type) {
	case nil:
		return b == nil
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case float64:
		bv, ok := b.(float64)
		return ok && av == bv
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !deepEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, v := range av {
			w, exists := bv[k]
			if !exists || !deepEqual(v, w) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

// Package events is the change event service: the durable per-document change
// log together with everything written on top of it.
//
// Within a document every change has a client-supplied id. New ids receive a
// monotonically increasing cursor; re-posting an existing id is idempotent
// only when the deviceId and decoded JSON payload match, otherwise it is a
// conflict. Valid batches commit atomically in one serialized transaction, so
// cursors never repeat and no record is partially written, even under
// concurrent writers. Ordinary posts, offline replays, merges and snapshot
// restores all allocate from the same per-document contiguous cursor space.
//
// A document may also carry snapshots: caller-supplied JSON states pinned to
// existing change cursors. Snapshots are write-once per cursor — a matching
// re-post is idempotent, a differing one a conflict — and live apart from the
// change log. A restore appends an ordinary change whose payload is a
// snapshot's state, recording its provenance so a repeated restore after a
// restart keeps the same idempotency/conflict decisions.
//
// Reads page by cursor in ascending order. The session view and the document
// view are the same read; the HTTP layer adds the session/permission checks.
// Long polling and push subscriptions are in-memory observers of commits:
// they register before the confirming read, hold no durable state, and are
// woken only after a change-bearing transaction has committed.
//
// The service owns only its own tables. The registration and permission
// layers are reached through its Gate interface, so a replay or merge never
// reaches into another service's storage.
package events

import (
	"encoding/json"
	"errors"
	"fmt"
)

// ErrStoreClosing reports that the service is shutting down and parked long
// polls have been woken so they can return without writing anything. The
// caller maps it to 503.
var ErrStoreClosing = errors.New("store is closing")

// Change is one element of an inbound batch or one row of a listing.
type Change struct {
	ID       string          // client-supplied change id, unique per document
	DeviceID string          // originating device
	Payload  json.RawMessage // decoded JSON value, stored verbatim
}

// Result reports the outcome for one element of an accepted batch.
type Result struct {
	ID      string `json:"id"`
	Created bool   `json:"created"`
	Cursor  int64  `json:"cursor"`
}

// ListedChange is one row in a ListChanges response.
type ListedChange struct {
	ID       string          `json:"id"`
	DeviceID string          `json:"deviceId"`
	Payload  json.RawMessage `json:"payload"`
	Cursor   int64           `json:"cursor"`
}

// MergeResult reports the outcome of an accepted MergeChange. Outcome is one
// of "idempotent", "applied" or "merged".
type MergeResult struct {
	ID      string  `json:"id"`
	Outcome string  `json:"outcome"`
	Cursor  int64   `json:"cursor"`
	Result  *Result `json:"result,omitempty"`
}

// ErrConflict reports that a batch references an existing change id with a
// different deviceId or payload. The whole batch is rejected.
type ErrConflict struct {
	ID string
}

func (e *ErrConflict) Error() string {
	return fmt.Sprintf("conflicting change %q for document", e.ID)
}

// ErrStaleCursor reports that a merge targets a base cursor for an unknown
// document, or a base cursor greater than the document's current cursor. The
// caller maps it to 400; nothing is written.
var ErrStaleCursor = errors.New("baseCursor is unknown or ahead of the current cursor")

// ErrSnapshotBase reports that a snapshot targets an unknown document or a
// cursor that is not an existing change cursor of the document. The caller
// maps it to 400; nothing is written.
var ErrSnapshotBase = errors.New("snapshot cursor is not an existing cursor of the document")

// ErrCompactedBase reports that a merge targets a base cursor below the
// document's compaction boundary: the changes it would be checked against
// have left the online log, so the conflict check cannot be completed. The
// caller maps it to 400; nothing is written.
var ErrCompactedBase = errors.New("baseCursor is below the compaction boundary")

// ErrSnapshotNotFound reports that no snapshot exists for the document and
// cursor. The caller maps it to 404.
var ErrSnapshotNotFound = errors.New("snapshot not found")

// ErrSnapshotConflict reports that a snapshot already exists for the document
// and cursor with a different state. The stored snapshot is left unchanged.
type ErrSnapshotConflict struct {
	Cursor int64
}

func (e *ErrSnapshotConflict) Error() string {
	return fmt.Sprintf("conflicting snapshot for cursor %d", e.Cursor)
}

// ErrRestoreConflict reports that a restore references a change id that is
// already taken by an ordinary change, or by a prior restore whose deviceId,
// snapshot cursor or source state differs. Nothing is written; the caller maps
// it to 409.
type ErrRestoreConflict struct {
	ID string
}

func (e *ErrRestoreConflict) Error() string {
	return fmt.Sprintf("change id %q conflicts with the change log", e.ID)
}

// ExportedSnapshot is one row of an ExportSnapshots result.
type ExportedSnapshot struct {
	Cursor int64           `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

// RestoreResult reports the outcome of an accepted RestoreSnapshot.
type RestoreResult struct {
	ID           string `json:"id"`
	Created      bool   `json:"created"`
	Cursor       int64  `json:"cursor"`
	RestoredFrom int64  `json:"restoredFrom"`
}

// schema is created when the service is constructed. Table and index shapes
// are unchanged from the pre-refactor layout, so data already on disk stays
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS changes (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	payload     BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
CREATE UNIQUE INDEX IF NOT EXISTS changes_doc_cursor_idx
	ON changes(document_id, cursor);
CREATE TABLE IF NOT EXISTS snapshots (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	state       BLOB NOT NULL,
	PRIMARY KEY (document_id, cursor)
);
CREATE TABLE IF NOT EXISTS restores (
	document_id     TEXT NOT NULL,
	change_id       TEXT NOT NULL,
	device_id       TEXT NOT NULL,
	snapshot_cursor INTEGER NOT NULL,
	change_cursor   INTEGER NOT NULL,
	state           BLOB NOT NULL,
	PRIMARY KEY (document_id, change_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS restores_doc_cursor_idx
	ON restores(document_id, change_cursor);
CREATE TABLE IF NOT EXISTS change_boundaries (
	document_id TEXT NOT NULL PRIMARY KEY,
	boundary    INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS change_identities (
	document_id   TEXT NOT NULL,
	id            TEXT NOT NULL,
	device_id     TEXT NOT NULL,
	digest        BLOB NOT NULL,
	cursor        INTEGER NOT NULL,
	restored_from INTEGER,
	PRIMARY KEY (document_id, id)
);
`

