139	// resolveChanges resolves every change id against existing rows inside tx,
140	// falling back to the retained summaries of compacted-away ids. A single
141	// device/payload mismatch aborts the whole batch before any cursor is
142	// allocated. It returns the per-id results and the indices of genuinely new
143	// changes that still need a cursor.
144	func resolveChanges(tx *sql.Tx, documentID string, changes []Change) ([]Result, []int, error) {
145		results := make([]Result, len(changes))
146		pending := make([]int, 0, len(changes))
147		for i, c := range changes {
