package events

import (
	"database/sql"
	"encoding/json"
	"errors"
	"sync"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// Gate is the only seam the change event service uses to reach the
// registration and permission layers. It is evaluated inside the caller's
// serialized transaction, so a rejected request never observes change
// content and the gate and the gated write commit as one judgment.
type Gate interface {
	// DeviceAuthorizedTx returns nil when deviceID is registered and currently
	// authorized for documentID, store.ErrDeviceNotFound when the device is not
	// registered and ErrPermissionDenied when its access was revoked.
	DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error
}

// Service is the change event service: the durable change log, snapshots and
// restores plus the in-memory long-poll and subscription observers of them.
type Service struct {
	db   *sql.DB
	gate Gate

	// mu guards waits, subs, nextWaitID, nextSubID and closed. Parked long
	// polls wait on a per-document set of channels; a committed change closes
	// (signals) every channel parked on it. WebSocket subscriptions live in a
	// second registry keyed by (document, device): a commit signals every
	// subscription under the document, while the permission service signals
	// only the matching device's subscriptions.
	mu       sync.Mutex
	waits    map[string]map[uint64]chan struct{}
	subs     map[subKey]map[uint64]*subscription
	nextWait uint64
	nextSub  uint64
	subWG    sync.WaitGroup
	closed   bool
}

// New constructs the change event service over the shared kernel handle and
// creates its tables. gate answers the registration/permission checks inside
// a write transaction; it may be nil for callers that only use the paths that
// do not gate (ordinary post, merge, snapshots, reads).
func New(kernel *store.Store, gate Gate) (*Service, error) {
	db := kernel.DB()
	if _, err := db.Exec(schema); err != nil {
		return nil, err
	}
	return &Service{
		db:    db,
		gate:  gate,
		waits: make(map[string]map[uint64]chan struct{}),
		subs:  make(map[subKey]map[uint64]*subscription),
	}, nil
}

// PostChanges validates and commits one batch atomically.
//
// Every change must have a non-empty id; duplicate ids within the batch are
// rejected by the caller before reaching this point. On conflict the returned
// error is *ErrConflict and nothing is written. Cursors are assigned in batch
// order to ids that do not yet exist. Results are returned in the same order
// as the input.
func (s *Service) PostChanges(documentID string, changes []Change) ([]Result, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	results, pending, err := resolveChanges(tx, documentID, changes)
	if err != nil {
		return nil, err
	}
	if err := appendPending(tx, documentID, changes, pending, results); err != nil {
		return nil, err
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		s.notifyWaiters(documentID)
	}
	return results, nil
}

// ReplayChanges commits a retried offline batch with exactly the same change
// semantics as PostChanges. It is the document-level replay entry of
// CommitAuthorized: the device id travels in the request body there.
func (s *Service) ReplayChanges(documentID string, changes []Change) ([]Result, error) {
	return s.CommitAuthorized(documentID, changes)
}

// CommitAuthorized validates and commits one batch atomically with exactly the
// same change semantics as PostChanges, but enforces the gate (registration
// then permission) first in the same transaction: an unregistered device
// yields store.ErrDeviceNotFound and a revoked device yields
// ErrPermissionDenied. None of those outcomes writes anything or exposes
// change content. It is shared by the offline replay and the session-scoped
// commit, whose device identity is resolved from the session before the
// call.
func (s *Service) CommitAuthorized(documentID string, changes []Change) ([]Result, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first: the device row and the permission row are read before any
	// change id is resolved, so a rejected replay cannot reveal content.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, changes[0].DeviceID); err != nil {
			return nil, err
		}
	}

	results, pending, err := resolveChanges(tx, documentID, changes)
	if err != nil {
		return nil, err
	}
	if err := appendPending(tx, documentID, changes, pending, results); err != nil {
		return nil, err
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		s.notifyWaiters(documentID)
	}
	return results, nil
}

// resolveChanges resolves every change id against existing rows inside tx,
// falling back to the retained summaries of compacted-away ids. A single
// device/payload mismatch aborts the whole batch before any cursor is
// allocated. It returns the per-id results and the indices of genuinely new
// changes that still need a cursor.
func resolveChanges(tx *sql.Tx, documentID string, changes []Change) ([]Result, []int, error) {
	results := make([]Result, len(changes))
	pending := make([]int, 0, len(changes))
	for i, c := range changes {
		var existingDevice string
		var existingPayload []byte
		var existingCursor int64
		err := tx.QueryRow(
			`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
			documentID, c.ID,
		).Scan(&existingCursor, &existingDevice, &existingPayload)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// No online row: the id may belong to a change compaction
			// trimmed, whose retained summary still decides idempotency.
			found, cursor, err := resolveTrimmedIdentity(tx, documentID, c)
			if err != nil {
				return nil, nil, err
			}
			if !found {
				pending = append(pending, i)
				continue
			}
			results[i] = Result{
				ID:      c.ID,
				Created: false,
				Cursor:  cursor,
			}
		case err != nil:
			return nil, nil, err
		default:
			if existingDevice != c.DeviceID || !store.JSONEqual(existingPayload, c.Payload) {
				return nil, nil, &ErrConflict{ID: c.ID}
			}
			results[i] = Result{
				ID:      c.ID,
				Created: false,
				Cursor:  existingCursor,
			}
		}
	}
	return results, pending, nil
}

// appendPending allocates contiguous cursors to the new change indices and
// inserts them in input order. It runs inside the caller's transaction. The
// allocation continues past the compaction boundary, so trimming the online
// log never makes the cursor space restart.
func appendPending(tx *sql.Tx, documentID string, changes []Change, pending []int, results []Result) error {
	nextCursor, err := currentCursorTx(tx, documentID)
	if err != nil {
		return err
	}
	nextCursor++
	for _, i := range pending {
		c := changes[i]
		if _, err := tx.Exec(
			`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
			documentID, nextCursor, c.ID, c.DeviceID, []byte(c.Payload),
		); err != nil {
			return err
		}
		results[i] = Result{
			ID:      c.ID,
			Created: true,
			Cursor:  nextCursor,
		}
		nextCursor++
	}
	return nil
}

// MergeChangeAuthorized is the session-scoped merge: it has exactly the merge
// semantics of MergeChange, but enforces the gate (registration then
// permission) first in the same serialized transaction: an unregistered device
// yields store.ErrDeviceNotFound and a revoked device yields
// ErrPermissionDenied. None of those outcomes writes anything or exposes
// change content. The device identity is resolved from the session by the HTTP
// layer before the call.
func (s *Service) MergeChangeAuthorized(documentID string, baseCursor int64, c Change) (MergeResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return MergeResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first: the device row and the permission row are read before any
	// change content is observed, so a rejected merge cannot reveal anything.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, c.DeviceID); err != nil {
			return MergeResult{}, err
		}
	}

	result, appended, err := mergeChangeTx(tx, documentID, baseCursor, c)
	if err != nil {
		return MergeResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return MergeResult{}, err
	}
	if appended {
		s.notifyWaiters(documentID)
	}
	return result, nil
}

// MergeChange validates and appends one change against a caller-observed base
// cursor, all within a single serialized transaction.
//
//   - An existing id is idempotent only when deviceId and the decoded payload
//     match (Outcome "idempotent", with the original Result); a mismatch is an
//     *ErrConflict and nothing is written.
//   - A new id with baseCursor equal to the current cursor is appended as
//     "applied".
//   - A new id with a base cursor behind the current one is appended as
//     "merged" only when every change after baseCursor carries a JSON object
//     payload whose top-level keys are disjoint from the new payload's; any
//     non-object later payload or shared key is an *ErrConflict.
//
// A non-zero baseCursor for an unknown document, or a baseCursor greater than
// the current cursor, returns ErrStaleCursor. A baseCursor below the
// compaction boundary returns ErrCompactedBase: the changes the merge would be
// checked against have left the online log, so the conflict check cannot be
// completed. An unknown document with baseCursor 0 accepts the first change as
// "applied".
func (s *Service) MergeChange(documentID string, baseCursor int64, c Change) (MergeResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return MergeResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	result, appended, err := mergeChangeTx(tx, documentID, baseCursor, c)
	if err != nil {
		return MergeResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return MergeResult{}, err
	}
	if appended {
		s.notifyWaiters(documentID)
	}
	return result, nil
}

// mergeChangeTx runs the merge judgment and (when allowed) the single append
// inside the caller's serialized transaction. It reports appended=true only
// when a new change row was inserted, so the caller wakes the push channels
// exactly once for a change-bearing commit; an idempotent re-post appends
// nothing and notifies nothing.
func mergeChangeTx(tx *sql.Tx, documentID string, baseCursor int64, c Change) (MergeResult, bool, error) {
	// Current cursor is the document's high-water mark (0 when unknown); it
	// never drops below the compaction boundary.
	current, err := currentCursorTx(tx, documentID)
	if err != nil {
		return MergeResult{}, false, err
	}
	if baseCursor > current || (baseCursor != 0 && current == 0) {
		return MergeResult{}, false, ErrStaleCursor
	}
	boundary, err := boundaryOfTx(tx, documentID)
	if err != nil {
		return MergeResult{}, false, err
	}
	if baseCursor < boundary {
		return MergeResult{}, false, ErrCompactedBase
	}

	// An existing id keeps the original idempotency/conflict rules.
	var existingDevice string
	var existingPayload []byte
	var existingCursor int64
	err = tx.QueryRow(
		`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
		documentID, c.ID,
	).Scan(&existingCursor, &existingDevice, &existingPayload)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No online row: a compacted-away id still answers from its retained
		// summary; anything else is a new id and falls through to the append
		// logic below.
		found, cursor, err := resolveTrimmedIdentity(tx, documentID, c)
		if err != nil {
			return MergeResult{}, false, err
		}
		if found {
			return MergeResult{
				ID:      c.ID,
				Outcome: "idempotent",
				Cursor:  cursor,
				Result: &Result{
					ID:      c.ID,
					Created: false,
					Cursor:  cursor,
				},
			}, false, nil
		}
	case err != nil:
		return MergeResult{}, false, err
	default:
		if existingDevice != c.DeviceID || !store.JSONEqual(existingPayload, c.Payload) {
			return MergeResult{}, false, &ErrConflict{ID: c.ID}
		}
		return MergeResult{
			ID:      c.ID,
			Outcome: "idempotent",
			Cursor:  existingCursor,
			Result: &Result{
				ID:      c.ID,
				Created: false,
				Cursor:  existingCursor,
			},
		}, false, nil
	}

	outcome := "applied"
	if baseCursor < current {
		// Merge is allowed only when every change after baseCursor is a JSON
		// object whose top-level keys do not collide with the new payload's.
		newKeys, err := objectKeys(c.Payload)
		if err != nil {
			if errors.Is(err, errNotObject) {
				return MergeResult{}, false, &ErrConflict{ID: c.ID}
			}
			return MergeResult{}, false, err
		}
		rows, err := tx.Query(
			`SELECT payload FROM changes
			 WHERE document_id = ? AND cursor > ?
			 ORDER BY cursor ASC`,
			documentID, baseCursor,
		)
		if err != nil {
			return MergeResult{}, false, err
		}
		for rows.Next() {
			var laterPayload []byte
			if err := rows.Scan(&laterPayload); err != nil {
				_ = rows.Close()
				return MergeResult{}, false, err
			}
			laterKeys, err := objectKeys(laterPayload)
			if err != nil {
				_ = rows.Close()
				if errors.Is(err, errNotObject) {
					return MergeResult{}, false, &ErrConflict{ID: c.ID}
				}
				return MergeResult{}, false, err
			}
			for k := range newKeys {
				if _, clash := laterKeys[k]; clash {
					_ = rows.Close()
					return MergeResult{}, false, &ErrConflict{ID: c.ID}
				}
			}
		}
		if err := rows.Err(); err != nil {
			_ = rows.Close()
			return MergeResult{}, false, err
		}
		_ = rows.Close()
		outcome = "merged"
	}

	next := current + 1
	if _, err := tx.Exec(
		`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
		documentID, next, c.ID, c.DeviceID, []byte(c.Payload),
	); err != nil {
		return MergeResult{}, false, err
	}
	return MergeResult{ID: c.ID, Outcome: outcome, Cursor: next}, true, nil
}

// errNotObject marks a payload that is not a JSON object.
var errNotObject = errors.New("payload is not a JSON object")

// objectKeys returns the top-level keys of a JSON object payload. A null,
// array or scalar payload yields errNotObject.
func objectKeys(raw json.RawMessage) (map[string]struct{}, error) {
	var m map[string]json.RawMessage
	if err := json.Unmarshal(raw, &m); err != nil {
		// Valid JSON that is not an object (array, scalar, null) decodes with
		// a type error into a map; treat it and malformed JSON as non-object.
		return nil, errNotObject
	}
	if m == nil {
		return nil, errNotObject
	}
	keys := make(map[string]struct{}, len(m))
	for k := range m {
		keys[k] = struct{}{}
	}
	return keys, nil
}

package events

import (
	"context"
	"database/sql"
	"time"
)

// DocumentExists reports whether documentID is a known document rather than an
// empty namespace: it has any online change row, or a compaction boundary from
// a log that was (fully or partially) trimmed.
func (s *Service) DocumentExists(documentID string) (bool, error) {
	var known bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)`,
		documentID, documentID,
	).Scan(&known); err != nil {
		return false, err
	}
	return known, nil
}

// ListChanges returns at most limit changes for documentID whose cursor is
// greater than after and still online, in cursor order, together with the
// cursor to pass as the next after value. An unknown document yields an empty
// list and cursor 0; a known document with no rows past after yields
// nextCursor == max(after, boundary), so a caller positioned inside the
// trimmed range resumes from the compaction boundary.
func (s *Service) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
	rows, err := s.db.Query(
		`SELECT id, device_id, payload, cursor FROM changes
		 WHERE document_id = ? AND cursor > ?
		 ORDER BY cursor ASC
		 LIMIT ?`,
		documentID, after, limit,
	)
	if err != nil {
		return nil, 0, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	var maxCursor int64 = after
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, 0, err
		}
		out = append(out, c)
		maxCursor = c.Cursor
	}
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}

	// Distinguish an unknown document from a known one with nothing new:
	// unknown documents must report nextCursor 0, while a known document
	// reports the greater of after and the compaction boundary.
	if len(out) == 0 {
		known, err := s.DocumentExists(documentID)
		if err != nil {
			return nil, 0, err
		}
		if !known {
			return out, 0, nil
		}
		boundary, err := boundaryOfTx(s.db, documentID)
		if err != nil {
			return nil, 0, err
		}
		if boundary > maxCursor {
			maxCursor = boundary
		}
	}
	return out, maxCursor, nil
}

// ExportChanges returns every change of documentID whose cursor lies in the
// closed interval [from, to] and is still in the online log, in ascending
// cursor order. When to is nil no upper bound is applied. An unknown document,
// or a range without any online change — including one that lies entirely
// inside the trimmed region — yields an empty list and no error: the export is
// a read that misses like any other. The (document_id, cursor) unique index
// guarantees a cursor appears at most once.
//
// The single SELECT runs as one SQLite statement over the serialized
// connection, so a batch committed concurrently is observed either with all of
// its rows or not at all — never half of it. The read starts no transaction,
// writes nothing and notifies no waiters, so it cannot move a cursor, produce
// a change record or wake a parked poll. Each returned row is the same record
// the paged read emits at that cursor.
func (s *Service) ExportChanges(documentID string, from int64, to *int64) ([]ListedChange, error) {
	var (
		rows *sql.Rows
		err  error
	)
	if to == nil {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ?
			 ORDER BY cursor ASC`,
			documentID, from,
		)
	} else {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ? AND cursor <= ?
			 ORDER BY cursor ASC`,
			documentID, from, *to,
		)
	}
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// WaitForChanges blocks until documentID has a change with cursor greater than
// after, a change is committed while waiting, wait elapses, ctx is canceled
// (the client disconnected) or the service stops. It then returns the current
// page of up to limit changes exactly as ListChanges would, with timedOut=true
// only when the wait deadline expired with no new rows.
//
// Registration precedes the first query: a commit landing between the read and
// the park still notifies a registered channel, so no change is missed.
//
// An unknown document is never parked on: it returns immediately with an empty
// list and nextCursor 0, timedOut=false. Data already past after is likewise
// returned immediately. wait <= 0 is an immediately expired deadline.
func (s *Service) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) (changes []ListedChange, nextCursor int64, timedOut bool, err error) {
	ch, remove := s.registerWait(documentID)
	defer remove()

	changes, nextCursor, err = s.ListChanges(documentID, after, limit)
	if err != nil || len(changes) > 0 {
		return changes, nextCursor, false, err
	}

	// Empty page: distinguish an unknown document (immediate empty/0, never
	// parked on) from a known document caught up to after.
	known, err := s.DocumentExists(documentID)
	if err != nil || !known {
		return changes, 0, false, err
	}

	// Known document, nothing new: a zero wait is an immediately expired
	// deadline; ListChanges already echoes nextCursor == after.
	if wait <= 0 {
		return changes, nextCursor, true, nil
	}

	timer := time.NewTimer(wait)
	defer timer.Stop()

	select {
	case <-ch:
		// Woken by a committed change, a whole-document deletion, or
		// InterruptWaits. A deleted document is an unknown document now: answer
		// an empty page at cursor 0 with timedOut=false rather than reporting a
		// deadline expiry. Any other empty re-read keeps the old timeout shape.
		s.mu.Lock()
		closing := s.closed
		s.mu.Unlock()
		if closing {
			return nil, 0, false, ErrStoreClosing
		}
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		if err != nil {
			return nil, 0, false, err
		}
		if len(changes) == 0 {
			known, knownErr := s.DocumentExists(documentID)
			if knownErr != nil {
				return nil, 0, false, knownErr
			}
			if !known {
				return changes, 0, false, nil
			}
		}
		return changes, nextCursor, len(changes) == 0, err
	case <-timer.C:
		// Timeout with no new rows: echo the caller's cursor without
		// advancing it. The document was known above, so ListChanges returns
		// nextCursor == after for an empty page.
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-ctx.Done():
		return nil, 0, false, ctx.Err()
	}
}

// registerWait parks a channel for documentID and returns it together with a
// removal function. The channel is closed on the next committed change to the
// document, or when the service stops.
func (s *Service) registerWait(documentID string) (ch chan struct{}, remove func()) {
	ch = make(chan struct{}, 1)

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		// Shutdown beat the registration: signal immediately so the caller does
		// not park on a channel nobody will close.
		close(ch)
		return ch, func() {}
	}
	s.nextWait++
	id := s.nextWait
	set := s.waits[documentID]
	if set == nil {
		set = make(map[uint64]chan struct{})
		s.waits[documentID] = set
	}
	set[id] = ch
	return ch, func() {
		s.mu.Lock()
		if set, ok := s.waits[documentID]; ok {
			delete(set, id)
			if len(set) == 0 {
				delete(s.waits, documentID)
			}
		}
		s.mu.Unlock()
	}
}

// notifyWaiters signals every long poll parked on documentID and every
// subscription open on it. It is called only after a change-bearing
// transaction has committed, so parked readers observe the new rows when they
// re-query and pushed frames describe committed changes.
func (s *Service) notifyWaiters(documentID string) {
	s.mu.Lock()
	set := s.waits[documentID]
	delete(s.waits, documentID)
	s.mu.Unlock()
	for _, ch := range set {
		close(ch)
	}
	s.signalSubscribers(documentID)
}

// Document-level deletion removes every durable row a document owns in the
// change event service: the online change log, the compaction boundary, the
// retained idempotency summaries of trimmed changes, snapshots and restore
// provenance. After the deletion the same document id is a brand-new document:
// an unknown document reads as an empty list at cursor 0, and the next commit
// allocates cursor 1 again, because every row — the boundary included — that
// remembered the old cursor space is gone.
//
// The work runs inside the caller's serialized transaction, sharing it with the
// CRDT state and permission-ledger deletions of the same operation, so a
// document deletion either removes every row or none; a document with no row
// in any of the services misses (ErrDocumentNotFound) and writes nothing.

package events

import (
	"errors"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// ErrDocumentNotFound reports that a delete targets a document id that has no
// durable data anywhere — it was never created or was already deleted. The
// caller maps it to 404; nothing is written.
var ErrDocumentNotFound = errors.New("document not found")

// DocumentDataExistsTx reports whether the change event service holds any row
// for documentID: an online change, a compaction boundary, a retained
// trimmed-id summary, a snapshot or a restore record. It runs inside the
// caller's transaction so the existence verdict is one judgment with the
// deletion that follows it.
func (s *Service) DocumentDataExistsTx(q store.DBTX, documentID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_identities WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM snapshots WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM restores WHERE document_id = ?)`,
		documentID, documentID, documentID, documentID, documentID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// DeleteDocumentDataTx removes every change-event row of documentID inside the
// caller's serialized transaction: the online log and restore records first
// (the rows that reference cursors), then snapshots, the retained idempotency
// summaries and finally the compaction boundary. With the boundary gone the
// cursor space restarts from 1 when the id is created again. It does not
// judge existence — the caller checks DocumentDataExistsTx (and the CRDT
// service's equivalent) once before deleting — so it never returns
// ErrDocumentNotFound on its own.
func (s *Service) DeleteDocumentDataTx(q store.DBTX, documentID string) error {
	stmts := []string{
		`DELETE FROM restores WHERE document_id = ?`,
		`DELETE FROM changes WHERE document_id = ?`,
		`DELETE FROM snapshots WHERE document_id = ?`,
		`DELETE FROM change_identities WHERE document_id = ?`,
		`DELETE FROM change_boundaries WHERE document_id = ?`,
	}
	for _, stmt := range stmts {
		if _, err := q.Exec(stmt, documentID); err != nil {
			return err
		}
	}
	return nil
}

package server

import (
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// handleDeleteDocument is the document-level data-cleanup entry:
//
//	DELETE /v1/documents/{documentID}?deviceId=D
//
// It removes one document's whole persisted data in a single serialized
// transaction. The calling device is declared by the deviceId query
// parameter — no new authentication is introduced and the call carries no
// body. The fixed verdict order is request shape (400, handled by routing and
// the empty-id guard) -> device existence (404) -> document permission (403)
// -> document existence (404); every failure writes nothing and cleans
// nothing. Success answers one compact JSON line naming the document id and
// the deletion marker and nothing else.
func handleDeleteDocument(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty
	deviceID := r.URL.Query().Get("deviceId")
	// A missing or empty deviceId is indistinguishable from an unregistered
	// caller; the gate also returns ErrDeviceNotFound for it, but judging here
	// keeps the 404 ahead of any document-content observation.
	if deviceID == "" {
		writeError(w, http.StatusNotFound, "device not found")
		return
	}

	if err := s.DeleteDocument(documentID, deviceID); err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		case errors.Is(err, events.ErrDocumentNotFound):
			writeError(w, http.StatusNotFound, "document not found")
		default:
			writeError(w, http.StatusInternalServerError, "failed to delete document")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"documentId": documentID, "deleted": true})
}

// malformedDocumentDelete reports whether a DELETE targets the document item
// resource /v1/documents/{documentID} but its path is not that exact shape:
// the document id segment is missing (the bare /v1/documents) or empty (a
// trailing slash), or one or more segments follow a non-empty id that are not
// a known document sub-resource with its own routes. Such a request is a
// malformed 400 JSON rather than ServeMux's redirect or plain-text 404; the
// delete surface never redirects or emits HTML.
//
// It only considers DELETE: wrong methods on the exact item path are rejected
// by the item route's method-less pattern, and non-DELETE requests keep their
// pre-existing routing. Known sub-resources (changes, snapshots, crdt,
// permissions, replay, merge, restore) own their shape checks and are left
// alone here; doubled-slash empty segments are already rejected by the guard
// itself before this runs.
func malformedDocumentDelete(method, p string) bool {
	if method != http.MethodDelete {
		return false
	}
	if p == "/v1/documents" {
		// Missing id segment entirely.
		return true
	}
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	if len(segs) == 1 {
		// Exactly one segment past the prefix: a trailing slash makes it the
		// empty id; a non-empty id is the well-formed item and is routed.
		return segs[0] == ""
	}
	// Two or more segments: known sub-resources keep their own endpoints and
	// malformed-shape guards; anything else past a non-empty id is a malformed
	// delete of the document item (extra segments).
	if segs[0] == "" {
		return false // doubled slash, already rejected upstream
	}
	switch segs[1] {
	case "changes", "snapshots", "crdt", "permissions", "replay", "merge", "restore":
		return false
	default:
		return true
	}
}

// Package app is the composition root: it opens the one shared database and
// constructs the three independently reusable internal services — the change
// event service, the permission service and the CRDT state service — wiring
// them together only through their internal interfaces.
//
// The services share one SQLite connection (the kernel opens a single
// pooled connection with immediate transactions), so a change commit, a CRDT
// submission or compaction, and a permission change are serialized on the
// same connection and leave no half-written batch. The change event and CRDT
// services take their registration-and-authorization verdict from the
// permission service inside their own transactions (events.Gate / crdt.Gate),
// and the permission service fans a committed revoke out to their
// subscription registries through authz.RevokeSink. No service reaches into
// another service's tables or fields.
//
// App is the single object the entry and HTTP layers use. It promotes each
// service's input/output boundary as its methods while hiding the wiring; it
// adds no authentication and exposes no endpoint of its own.
package app

import (
	"context"
	"encoding/json"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/authz"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/push"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// App composes the durable kernel and the three internal services over one
// shared database connection.
type App struct {
	*store.Store

	events *events.Service
	crdt   *crdt.Service

	// pushSubs is the process-wide, in-memory registry of the live push
	// connections across both channels. It backs the device-scoped
	// subscription management endpoints and holds no durable state.
	pushSubs *push.Registry

	// Authz is the permission service. It is exposed so the HTTP layer can
	// grant/revoke and read authorization directly; the other services reach
	// it through their gates rather than this field.
	Authz *authz.Service
}

// Open opens (creating if needed) the SQLite database at path and constructs
// every internal service over it. The empty path opens a private in-memory
// database useful for tests. A construction failure closes the kernel and
// leaves nothing behind.
func Open(path string) (*App, error) {
	kernel, err := store.Open(path)
	if err != nil {
		return nil, err
	}

	// The permission service is built first: its gate is a constructor
	// dependency of the change event and CRDT services.
	permissions, err := authz.New(kernel)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	eventService, err := events.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	crdtService, err := crdt.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}

	// A committed revoke ends the affected live subscriptions in both
	// push channels. The dependency is an interface, registered once here, so
	// the permission service never names either subscriber concretely.
	permissions.AddRevokeSink(eventsRevokeSink{eventService})
	permissions.AddRevokeSink(crdtService)

	return &App{
		Store:    kernel,
		events:   eventService,
		crdt:     crdtService,
		Authz:    permissions,
		pushSubs: push.NewRegistry(),
	}, nil
}

// eventsRevokeSink adapts the change event service's revoke hook to the
// permission service's RevokeSink interface.
type eventsRevokeSink struct{ e *events.Service }

func (s eventsRevokeSink) PermissionRevoked(documentID, deviceID string) {
	s.e.SignalRevoked(documentID, deviceID)
}

// Events returns the change event service.
func (a *App) Events() *events.Service { return a.events }

// CRDT returns the CRDT state service.
func (a *App) CRDT() *crdt.Service { return a.crdt }

// ---- Change event service boundary (promoted so the entry layer has one
// object; each method delegates verbatim to the events service). ----

// InterruptWaits wakes every parked long poll and every live change-log and
// CRDT subscription without closing the database, so an orderly shutdown
// drains waiting connections (long polls answer 503; subscriptions finish
// with the going-away close) instead of holding the drain hostage.
func (a *App) InterruptWaits() {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
}

// Closing reports whether shutdown has begun, covering both push channels.
func (a *App) Closing() bool {
	return a.events.Closing() || a.crdt.Closing()
}

// Close interrupts the in-memory observers, waits for every subscription
// handler to unregister and then releases the shared database handle.
func (a *App) Close() error {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
	a.events.WaitDrained()
	a.crdt.WaitDrained()
	return a.Store.Close()
}

// PostChanges delegates to the change event service.
func (a *App) PostChanges(documentID string, changes []events.Change) ([]events.Result, error) {
	return a.events.PostChanges(documentID, changes)
}

// ReplayChanges delegates to the change event service.
func (a *App) ReplayChanges(documentID string, changes []events.Change) ([]events.Result, error) {
	return a.events.ReplayChanges(documentID, changes)
