1	package events
2	
3	// subKey identifies the set of subscriptions belonging to one device's view
4	// of one document: change commits wake every device set under the document,
5	// a permission revoke closes only the one (document, device) set.
6	type subKey struct {
7		document string
8		device   string
9	}
10	
11	// subscription is one in-memory, push-only observer of the change log.
12	//
13	// It belongs to a (document, device) pair — the device is the one owning the
14	// session that opened the connection. It receives one coalesceable signal per
15	// change-producing commit (PostChanges, ReplayChanges, MergeChange and
16	// RestoreSnapshot all signal through the same hook long polling uses). The
17	// permission service closes the separate one-shot revoked channel when it
18	// revokes the keyed pair; closing is sticky, so a later grant never reopens
19	// it.
20	//
21	// A subscription leaves no durable trace: nothing is written, a disconnect
22	// simply unregisters, and a stop broadcasts one final wakeup. Pushing never
23	// allocates a cursor or inserts a change row.
24	type subscription struct {
25		// wakes receives one value on every change commit for the keyed document.
26		// It is buffered (and signals coalesce) so a commit is never dropped or
27		// blocked while the consumer is reading the log.
28		wakes chan struct{}
29		// revoked is closed once, the first time permission for the keyed pair is
30		// revoked while this subscription is live. Closing is sticky.
31		revoked       chan struct{}
32		revokedClosed bool
33		// deleted is closed once, when the keyed document is deleted as a whole
34		// while this subscription is live. The connection then ends with the
35		// document-deleted close code; closing is sticky, so a document later
36		// re-created under the same id never reopens a subscription the deletion
37		// already ended.
38		deleted       chan struct{}
39		deletedClosed bool
40	}
41	
42	// AddSubscription registers an in-memory subscription for documentID as seen
43	// by deviceID. It returns:
44	//
45	//   - wakes: signaled (coalesceably) after every change commit on documentID;
46	//   - revoked: closed once if/when permission for (documentID, deviceID) is
47	//     revoked while the subscription is live;
48	//   - deleted: closed once when documentID is deleted as a whole while the
49	//     subscription is live;
50	//   - unregister: idempotent removal; a client disconnect, a permission close,
51	//     a document-deletion close and a service stop may all race to call it.
52	//
53	// If the service is already stopping the wake channel is signaled immediately
54	// and unregister is a no-op, so a late subscriber parks on nothing.
55	func (s *Service) AddSubscription(documentID, deviceID string) (wakes <-chan struct{}, revoked <-chan struct{}, deleted <-chan struct{}, unregister func()) {
56		ch := make(chan struct{}, 1)
57		sub := &subscription{wakes: ch, revoked: make(chan struct{}), deleted: make(chan struct{})}
58		key := subKey{document: documentID, device: deviceID}
59	
60		s.mu.Lock()
61		defer s.mu.Unlock()
62		if s.closed {
63			close(ch)
64			return ch, sub.revoked, sub.deleted, func() {}
65		}
66		s.subWG.Add(1)
67		s.nextSub++
68		id := s.nextSub
69		set := s.subs[key]
70		if set == nil {
71			set = make(map[uint64]*subscription)
72			s.subs[key] = set
73		}
74		set[id] = sub
75		remove := func() {
76			s.mu.Lock()
77			if set, ok := s.subs[key]; ok {
78				if _, ok := set[id]; ok {
79					delete(set, id)
80					if len(set) == 0 {
81						delete(s.subs, key)
82					}
83					s.mu.Unlock()
84					s.subWG.Done()
85					return
86				}
87			}
88			s.mu.Unlock()
89		}
90		return ch, sub.revoked, sub.deleted, remove
91	}
92	
93	// signalSubscribers wakes every subscription open on documentID. It is called
94	// only after a change-bearing transaction has committed, so when a woken
95	// subscription re-reads the log the new rows are visible.
96	func (s *Service) signalSubscribers(documentID string) {
97		s.mu.Lock()
98		var targets []chan struct{}
99		for key, set := range s.subs {
100			if key.document != documentID {
101				continue
102			}
103			for _, sub := range set {
104				targets = append(targets, sub.wakes)
105			}
106		}
107		s.mu.Unlock()
108	
109		for _, ch := range targets {
110			select {
111			case ch <- struct{}{}:
112			default:
113				// A signal the consumer has not drained yet is already pending; the
114				// pending wake covers this commit too because the consumer re-reads
115				// from its last observed cursor.
116			}
117		}
118	}
119	
120	// SignalRevoked closes the one-shot revoked channel of every subscription open
121	// on (documentID, deviceID), so the connection layer ends those subscriptions
122	// with the permission-closed code even if a grant races in afterward. Other
123	// devices' and other documents' subscriptions are untouched. It is the
124	// permission service's revoke hook for the change event service.
125	func (s *Service) SignalRevoked(documentID, deviceID string) {
126		s.mu.Lock()
127		set := s.subs[subKey{document: documentID, device: deviceID}]
128		targets := make([]*subscription, 0, len(set))
129		for _, sub := range set {
130			if !sub.revokedClosed {
131				sub.revokedClosed = true
132				targets = append(targets, sub)
133			}
134		}
135		s.mu.Unlock()
136	
137		for _, sub := range targets {
138			close(sub.revoked)
139		}
140	}
141	
142	// SignalDeviceDeregistered ends every live subscription belonging to
143	// deviceID across every document, after the device's deregistration
144	// transaction committed: the session backing such a connection is already
145	// hard-deleted, so the connection closes immediately with the same
146	// permission-closed code a revoke uses — stickily, nothing can reopen it.
147	// Other devices' subscriptions are untouched.
148	func (s *Service) SignalDeviceDeregistered(deviceID string) {
149		s.mu.Lock()
150		var targets []*subscription
151		for key, set := range s.subs {
152			if key.device != deviceID {
153				continue
154			}
155			for _, sub := range set {
156				if !sub.revokedClosed {
157					sub.revokedClosed = true
158					targets = append(targets, sub)
159				}
160			}
161		}
162		s.mu.Unlock()
163	
164		for _, sub := range targets {
165			close(sub.revoked)
166		}
167	}
168	
169	// SignalDocumentDeleted ends every live subscription open on documentID,
170	// across every device, after the document's deletion transaction committed:
171	// all of its durable data is already gone, so each connection closes
172	// immediately with the document-deleted code, stickily — a document later
173	// re-created under the same id never reopens these subscriptions. Other
174	// documents' subscriptions are untouched.
175	func (s *Service) SignalDocumentDeleted(documentID string) {
176		s.mu.Lock()
177		var targets []*subscription
178		for key, set := range s.subs {
179			if key.document != documentID {
180				continue
181			}
182			for _, sub := range set {
183				if !sub.deletedClosed {
184					sub.deletedClosed = true
185					targets = append(targets, sub)
186				}
187			}
188		}
189		// Wake long polls parked on the document so they re-read at once and answer
190		// as they do for any now-unknown document (empty list, cursor 0) instead of
191		// holding until their wait deadline. The WebSocket subscriptions are ended
192		// through their deleted channels, not their wake channels.
193		waits := s.waits[documentID]
194		delete(s.waits, documentID)
195		s.mu.Unlock()
196	
197		for _, ch := range waits {
198			close(ch)
199		}
200		for _, sub := range targets {
201			close(sub.deleted)
202		}
203	}
204	
205	// Closing reports whether the service has begun stopping. A woken subscription
206	// uses it to distinguish a termination signal from a commit.
207	func (s *Service) Closing() bool {
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		return s.closed
211	}
212	
213	// interruptWaits wakes every parked long poll without closing the database, so
214	// an orderly shutdown drains waiting connections immediately (they answer 503)
215	// instead of holding shutdown hostage until their wait deadline. Committed
216	// state is untouched. Live subscriptions get one last wakeup as well; the
217	// connection layer re-checks the closed flag and finishes with a going-away
218	// close.
219	func (s *Service) InterruptWaits() {
220		s.mu.Lock()
221		s.closed = true
