14	// states, after first seeding enough changes for the cursors to exist.
15	func seedSnapshots(t *testing.T, h http.Handler, doc string, states map[int]string) {
16		t.Helper()
17		max := 0
18		for c := range states {
19			if c > max {
20				max = c
21			}
