33	func TestExportSnapshotsHTTPSuccess(t *testing.T) {
34		h, _ := newTestHandler(t)
35		seedSnapshots(t, h, "doc1", map[int]string{
36			1: "null",
37			2: `42`,
38			3: `"str"`,
39			4: `[1,2]`,
40			5: `{"a":1}`,
41		})
42	
43		// No parameters: from defaults to 0, no upper bound. The body is one
44		// compact line with keys ordered snapshots,count and item keys ordered
45		// cursor,state; exactly one trailing newline.
46		w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots")
47		if w.Code != http.StatusOK {
48			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
49		}
50		if ct := w.Header().Get("Content-Type"); ct != "application/json" {
51			t.Fatalf("content type = %q", ct)
52		}
