18	func deleteDocument(t *testing.T, srv *httptest.Server, doc, device string) (int, string, string) {
19		t.Helper()
20		return rawRequest(t, srv, http.MethodDelete,
21			"/v1/documents/"+doc+"?deviceId="+device)
22	}
