24	// Successful deletion answers one compact JSON line plus a trailing newline
25	// naming exactly the document id and the deletion marker.
26	func TestDeleteDocumentSuccessShape(t *testing.T) {
27		h, _ := newTestHandler(t)
28		registerDevice(t, h, "dev-1")
29		w, _ := postJSON(t, h, "/v1/documents/doc-1/changes", map[string]any{
30			"deviceId": "dev-1",
31			"changes":  []any{map[string]any{"id": "c1", "payload": map[string]any{"n": 1}}},
32		})
33		if w.Code != http.StatusOK {
34			t.Fatal(w.Body.String())
35		}
36	
37		w, _ = doRequest(t, h, http.MethodDelete, "/v1/documents/doc-1?deviceId=dev-1")
38		if w.Code != http.StatusOK {
39			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
40		}
41		if ct := w.Header().Get("Content-Type"); ct != "application/json" {
42			t.Fatalf("content type = %q", ct)
43		}
44		if got := w.Body.String(); got != `{"deleted":true,"documentId":"doc-1"}`+"\n" {
45			t.Fatalf("body = %q, want the id and deletion marker on one line", got)
46		}
47	}
48	
49	// The reads differ before and after the delete: the change log, a snapshot and
50	// the CRDT state are all reachable beforehand and all miss afterward, while a
51	// second document is untouched.
52	func TestDeleteDocumentClearsAllLayers(t *testing.T) {
53		srv, _ := newWSTestServer(t)
54		registerDeviceViaHTTP(t, srv, "dev-1")
55	
56		// Two documents share the process; only doc-a is deleted.
