61			"cursor": 1, "state": map[string]any{"n": 1},
62		}); code != http.StatusOK {
63			t.Fatalf("snapshot = %d", code)
64		}
65		// CRDT state on doc-a.
66		if code := postCRDTOps(t, srv, "doc-a", map[string]any{
67			"deviceId": "dev-1", "type": "counter",
68			"ops": []any{crdtCounterOp("op-1", 5)},
69		}); code != http.StatusOK {
