func TestSessionVersionRegisterBadBody(t *testing.T) {
	h, _ := newTestHandler(t)
	seedSessionVersions(t, h, "dev", "sess", "doc1")

	for _, body := range []string{
		`{"cursor":1}`, `{"name":""}`, `{"name":"x","cursor":0}`,
